// ============================================
// DEAD LETTER QUEUE - обработка ошибок
// ============================================

const failed = $input.first().json;

console.log('💀 ОШИБКА В DEAD LETTER QUEUE');
console.log(`📦 Заказ: ${failed.task?.orderId}`);
console.log(`❌ Ошибка: ${failed.error?.message}`);
console.log(`🔁 Попыток: ${failed.error?.retryCount || 0}`);

// Сохраняем ошибку в Event Store
await $http.post('/webhook/event-store', {
  body: {
    eventId: 'err_' + Date.now(),
    eventType: 'order.failed',
    timestamp: new Date().toISOString(),
    data: {
      orderId: failed.task?.orderId,
      taskId: failed.task?.taskId,
      error: failed.error?.message,
      retryCount: failed.error?.retryCount || 0
    },
    source: 'dead-letter-queue'
  }
});

return [{
  json: {
    processed: true,
    taskId: failed.task?.taskId,
    orderId: failed.task?.orderId,
    error: failed.error?.message,
    action: 'logged'
  }
}];

// ============================================
// ОТПРАВКА В EVENT STORE (Dead Letter Queue)
// ============================================

const data = $input.first().json;

// Формируем событие
const eventData = {
  eventId: 'err_' + Date.now(),
  eventType: 'error.logged',
  timestamp: new Date().toISOString(),
  data: {
    orderId: data.orderId,
    error: data.error
  },
  source: 'dead-letter-queue'
};

console.log('💀 Отправляем в Event Store:', eventData);

// Отправляем HTTP запрос
await $http.post('/webhook/event-store', {
  headers: {
    'Content-Type': 'application/json'
  },
  body: eventData
});

console.log('✅ Событие ошибки сохранено');

return [data];
